        function updateLinkStyle() {
            if (isMobileDevice()) {
                link.classList.add('gradient-text');
            } else {
                link.classList.remove('gradient-text');
            }
        }

        // Initial call to set the link style
        updateLinkStyle();

        // Add event listener for window resize to update the link style
        window.addEventListener('resize', updateLinkStyle);
