function get_users($conn, $page = 1, $items_per_page = 10, $sort_by = 'id', $sort_order = 'ASC', $search_criteria = []) {
    // Default query
    $query = "SELECT * FROM users";
    $where_clauses = [];
    $params = [];

    // Handle search criteria
    if (!empty($search_criteria)) {
        $search_conditions = [];

        // Process each search condition
        foreach ($search_criteria as $field => $value) {
            if (is_array($value)) {
                // Handle operators like AND, OR, NOT
                $operator = $value[0];
                $search_value = $value[1];

                if ($operator === 'NOT') {
                    $search_conditions[] = "$field NOT LIKE ?";
                } else {
                    $search_conditions[] = "$field LIKE ?";
                }
                $params[] = "%$search_value%";
            } else {
                // Simple search without operator
                $search_conditions[] = "$field LIKE ?";
                $params[] = "%$value%";
            }
        }

        // Combine search conditions with AND
        $where_clauses[] = '(' . implode(' AND ', $search_conditions) . ')';
    }

    // Handle sorting
    $sort_order = strtoupper($sort_order);
    if ($sort_order === 'ASC' || $sort_order === 'DESC') {
        $query .= " ORDER BY $sort_by $sort_order";
    }

    // Handle pagination
    $offset = ($page - 1) * $items_per_page;
    $query .= " LIMIT $items_per_page OFFSET $offset";

    // Prepare and execute the query
    $stmt = $conn->prepare($query);
    if (!empty($where_clauses)) {
        $query = "SELECT * FROM users " . implode(' ', $where_clauses) . " " . $query;
        $stmt = $conn->prepare($query);
    }

    if ($stmt) {
        $stmt->bind_param(str_repeat('s', count($params)), ...$params);
        $stmt->execute();
        $result = $stmt->get_result();
        $users = $result->fetch_all(MYSQLI_ASSOC);
        $stmt->close();
    } else {
        $users = [];
    }

    return $users;
}
